#!/usr/bin/env node
// Design-token tool. Zero dependencies so it runs before `pnpm install`.
//   node scripts/tokens.mjs build   → writes tokens.css + tailwind-theme.css
//   node scripts/tokens.mjs check   → WCAG contrast report; fails on any pair below its minimum
//                                     or if the generated files are stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const themeDir = join(root, 'apps/web/src/theme');
const tokens = JSON.parse(readFileSync(join(themeDir, 'tokens.json'), 'utf8'));
const HEADER = '/* GENERATED by scripts/tokens.mjs from tokens.json — do not edit by hand. */\n';

const block = (vars) =>
  Object.entries(vars)
    .map(([k, v]) => `  ${k}: ${v};`)
    .join('\n');

function themeVars(mode) {
  const vars = {};
  for (const [k, v] of Object.entries(tokens.color[mode])) vars[`--rb-color-${k}`] = v;
  for (const [k, v] of Object.entries(tokens.shadow[mode])) vars[`--rb-shadow-${k}`] = v;
  vars['color-scheme'] = mode;
  return vars;
}

function staticVars() {
  const vars = {
    '--rb-font-sans': tokens.font.sans,
    '--rb-font-ml': tokens.font.ml,
  };
  for (const [k, v] of Object.entries(tokens.space)) vars[`--rb-space-${k}`] = v;
  for (const [k, v] of Object.entries(tokens.radius)) vars[`--rb-radius-${k}`] = v;
  for (const [k, v] of Object.entries(tokens.size)) vars[`--rb-size-${k}`] = v;
  for (const [k, [size, lh, lhMl, weight]] of Object.entries(tokens.type)) {
    if (k.startsWith('$')) continue;
    vars[`--rb-text-${k}`] = size;
    vars[`--rb-leading-${k}`] = lh;
    vars[`--rb-leading-${k}-ml`] = lhMl;
    vars[`--rb-weight-${k}`] = weight;
  }
  return vars;
}

// Line-heights follow the content language: Malayalam needs taller lines for stacked conjuncts.
// Utilities read --rb-leading-<size>, which these blocks switch per [lang] (nearest ancestor wins).
function leadingVars(variant) {
  const vars = {};
  for (const [k, [, lh, lhMl]] of Object.entries(tokens.type)) {
    if (k.startsWith('$')) continue;
    vars[`--rb-leading-${k}`] = variant === 'ml' ? lhMl : lh;
  }
  return vars;
}

function buildTokensCss() {
  const s = tokens.textScale;
  return (
    HEADER +
    `:root {\n${block(staticVars())}\n}\n\n` +
    `[lang='ml'] {\n${block(leadingVars('ml'))}\n}\n\n` +
    `[lang='en'] {\n${block(leadingVars('en'))}\n}\n\n` +
    `:root,\n:root[data-theme='light'] {\n${block(themeVars('light'))}\n}\n\n` +
    `@media (prefers-color-scheme: dark) {\n  :root:not([data-theme='light']) {\n${block(themeVars('dark')).replace(/^/gm, '  ')}\n  }\n}\n\n` +
    `:root[data-theme='dark'] {\n${block(themeVars('dark'))}\n}\n\n` +
    `html { font-size: ${s.normal}; }\n` +
    `html[data-text-size='large'] { font-size: ${s.large}; }\n` +
    `html[data-text-size='xl'] { font-size: ${s.xl}; }\n`
  );
}

// Tailwind v4 maps utilities (bg-surface, text-muted, rounded-lg, …) onto the runtime CSS variables,
// so themes and text sizes switch without rebuilding.
function buildTailwindTheme() {
  const lines = [];
  for (const k of Object.keys(tokens.color.light)) lines.push(`  --color-${k}: var(--rb-color-${k});`);
  for (const k of Object.keys(tokens.radius)) lines.push(`  --radius-${k}: var(--rb-radius-${k});`);
  for (const k of Object.keys(tokens.shadow.light)) lines.push(`  --shadow-${k}: var(--rb-shadow-${k});`);
  for (const k of Object.keys(tokens.type)) {
    if (k.startsWith('$')) continue;
    lines.push(`  --text-${k}: var(--rb-text-${k});`);
    lines.push(`  --text-${k}--line-height: var(--rb-leading-${k});`);
    lines.push(`  --text-${k}--font-weight: var(--rb-weight-${k});`);
  }
  for (const k of Object.keys(tokens.size)) lines.push(`  --spacing-${k}: var(--rb-size-${k});`);
  lines.push('  --font-sans: var(--rb-font-sans);', '  --font-ml: var(--rb-font-ml);');
  return HEADER + `@theme inline {\n${lines.join('\n')}\n}\n`;
}

// WCAG 2.x relative luminance and contrast ratio.
function luminance(hex) {
  const n = hex.replace('#', '');
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(n.slice(i, i + 2), 16) / 255);
  const lin = (c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}
export function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

const outputs = {
  'tokens.css': buildTokensCss(),
  'tailwind-theme.css': buildTailwindTheme(),
};

const cmd = process.argv[2];
if (cmd === 'build') {
  for (const [file, css] of Object.entries(outputs)) writeFileSync(join(themeDir, file), css);
  console.log('tokens: wrote', Object.keys(outputs).join(', '));
} else if (cmd === 'check') {
  let failures = 0;
  for (const mode of ['light', 'dark']) {
    console.log(`\n${mode.toUpperCase()}`);
    for (const [fg, bg, min] of tokens.contrast.pairs) {
      const ratio = contrast(tokens.color[mode][fg], tokens.color[mode][bg]);
      const ok = ratio >= min;
      if (!ok) failures++;
      console.log(`  ${ok ? 'pass' : 'FAIL'}  ${ratio.toFixed(2).padStart(5)} ≥ ${min}  ${fg} on ${bg}`);
    }
  }
  for (const [file, css] of Object.entries(outputs)) {
    let current = '';
    try {
      current = readFileSync(join(themeDir, file), 'utf8');
    } catch {
      // missing file counts as stale
    }
    if (current !== css) {
      failures++;
      console.log(`\nFAIL  ${file} is stale — run \`pnpm tokens\``);
    }
  }
  console.log(
    failures ? `\n${failures} problem(s)` : '\nAll contrast pairs pass; generated files are fresh.',
  );
  process.exit(failures ? 1 : 0);
} else {
  console.error('usage: tokens.mjs build|check');
  process.exit(2);
}
